            0 => Some(Self::zero()),
            1 => Some(if sign == Minus {
                Self::minus_one()
            } else {
                Self::one()
            }),
            _ => Self::small_integer(sign, magnitude),
        };
        if let Some(cached) = cached {
            return cached;
        }
    }
    Self::from_bigint(n.clone())
